      // Draw main route (blue)
      const mainRouteCoords = selectedOrderForWorkspace.routeOptimization.mainRoute.waypoints;
      (L.polyline as any)(mainRouteCoords, {
        color: 'blue',
        weight: 4,
        opacity: 0.7,
        dashArray: '10, 10'
